export const assetCategories=[['all','全部'],['writing','写作'],['literature','文献'],['detection','检测'],['presentation','演示'],['research','图表'],['format','排版']];
export function assetCategory(a){if(a.type==='report'||a.tool==='aigc')return 'detection';if(a.tool==='format')return 'format';if(a.tool==='research')return 'research';if(a.tool==='ppt')return 'presentation';if(['search','reading','summary','translation'].includes(a.tool))return 'literature';return 'writing';}
export function selectAssets(assets,{category='all',project='all',query='',sort='updated'}={},projects=[]){const names=new Map(projects.map(p=>[p.id,p.name]));const q=query.trim().toLocaleLowerCase();return assets.filter(a=>(category==='all'||assetCategory(a)===category)&&(project==='all'||(project==='none'?!a.projectId:a.projectId===project))&&(!q||[a.title,a.kind,names.get(a.projectId)||'未归入项目'].join(' ').toLocaleLowerCase().includes(q))).sort((a,b)=>sort==='name'?a.title.localeCompare(b.title,'zh-CN')||b.stamp-a.stamp:sort==='created'?(Date.parse(b.data.createdAt)||Number(b.id)||b.stamp)-(Date.parse(a.data.createdAt)||Number(a.id)||a.stamp):b.stamp-a.stamp);}
